workerInstructions.schemaGuidance:
The handoff file named spec.json is the canonical spec artifact payload.
Write valid JSON that matches this schema exactly; do not add properties outside the schema.
The CLI validates the payload before it can be sealed or published.
Spec artifact schema:
{
  "type": "object",
  "required": [
    "goal",
    "scope",
    "constraints",
    "design_principles",
    "overview",
    "background",
    "requirements",
    "acceptance_criteria",
    "clarifications",
    "alternatives_considered",
    "open_questions",
    "tasks"
  ],
  "additionalProperties": false,
  "properties": {
    "goal": {
      "type": "string"
    },
    "capabilities": {
      "type": "object",
      "additionalProperties": {
        "type": "boolean"
      }
    },
    "background": {
      "type": "string"
    },
    "scope": {
      "type": "object",
      "required": [
        "in",
        "out"
      ],
      "additionalProperties": false,
      "properties": {
        "in": {
          "type": "array",
          "items": {
            "type": "string"
          }
        },
        "out": {
          "type": "array",
          "items": {
            "type": "string"
          }
        }
      }
    },
    "constraints": {
      "type": "array",
      "items": {
        "type": "string"
      }
    },
    "design_principles": {
      "type": "array",
      "items": {
        "type": "string"
      }
    },
    "overview": {
      "type": "object",
      "required": [
        "modules",
        "data_flow",
        "decisions"
      ],
      "additionalProperties": false,
      "properties": {
        "modules": {
          "type": "array",
          "maxItems": 200,
          "items": {
            "type": "object",
            "required": [
              "text"
            ],
            "additionalProperties": false,
            "properties": {
              "text": {
                "type": "string",
                "maxLength": 500
              },
              "added_by_task": {
                "type": "string",
                "maxLength": 100
              }
            }
          }
        },
        "data_flow": {
          "type": "array",
          "maxItems": 200,
          "items": {
            "type": "object",
            "required": [
              "text"
            ],
            "additionalProperties": false,
            "properties": {
              "text": {
                "type": "string",
                "maxLength": 500
              },
              "added_by_task": {
                "type": "string",
                "maxLength": 100
              }
            }
          }
        },
        "decisions": {
          "type": "array",
          "maxItems": 200,
          "items": {
            "type": "object",
            "required": [
              "text"
            ],
            "additionalProperties": false,
            "properties": {
              "text": {
                "type": "string",
                "maxLength": 500
              },
              "evidence": {
                "type": "string",
                "maxLength": 1000
              },
              "consideredAlternatives": {
                "type": "string",
                "maxLength": 1000
