          "type": "boolean"
        },
        "confirmed_at": {
          "type": "string"
        },
        "notes": {
          "type": "string"
        }
      }
    },
    "tasks": {
      "type": "array",
      "maxItems": 200,
      "items": {
        "type": "object",
        "required": [
          "id",
          "title",
          "goal",
          "origin",
          "added_round",
          "status"
        ],
        "additionalProperties": false,
        "properties": {
          "id": {
            "type": "string",
            "minLength": 1,
            "maxLength": 100,
            "pattern": "^[A-Za-z0-9][A-Za-z0-9_-]{0,99}$"
          },
          "title": {
            "type": "string",
            "minLength": 1,
            "maxLength": 200
          },
          "goal": {
            "type": "string",
            "minLength": 1,
            "maxLength": 1000
          },
          "acceptance": {
            "type": "array",
            "maxItems": 50,
            "items": {
              "type": "string",
              "minLength": 1,
              "maxLength": 500
            }
          },
          "implementation_notes": {
            "type": "string",
            "maxLength": 5000
          },
          "test_strategy": {
            "type": "string",
            "maxLength": 2000
          },
          "parent": {
            "type": [
              "string",
